"""Read LittleCMS's public header: pixel format macros and exported functions."""

from __future__ import annotations

import re
from pathlib import Path

from ._paths import EXT

TYPE_RE = re.compile(r"^#define\s+TYPE_(\w+)\s+[(T]", re.MULTILINE)
CMSAPI_RE = re.compile(r"CMSEXPORT\s+(\w+)\s*\(")
TABLE = EXT / "formats_table.h"

PREAMBLE = """\
/* Pixel formats of LittleCMS {version}: every TYPE_* macro of lcms2.h.
 *
 * Generated by `python scripts/dev.py lcms2 formats` from vendor/Little-CMS/include/lcms2.h.
 * Do not edit by hand.
 */
#ifndef LCMS2_FORMATS_TABLE_H
#define LCMS2_FORMATS_TABLE_H

typedef struct {{
    const char *name;
    cmsUInt32Number value;
}} lcms2_format_entry;

static const lcms2_format_entry lcms2_format_table[] = {{
"""

POSTAMBLE = """\
    {NULL, 0},
};

#endif
"""


def format_names(header_text: str) -> list[str]:
    """Names of the ``TYPE_*`` pixel-format macros, without the prefix, in header order."""
    return TYPE_RE.findall(header_text)


def cmsapi_functions(header_text: str) -> set[str]:
    """Names of every exported (``CMSEXPORT``) function declared in the header."""
    return set(CMSAPI_RE.findall(header_text))


def lcms_version(header_text: str) -> str:
    """``"2.20"`` from ``#define LCMS_VERSION 2200``."""
    m = re.search(r"^#define\s+LCMS_VERSION\s+(\d+)", header_text, re.MULTILINE)
    if m is None:
        raise ValueError("LCMS_VERSION not found in lcms2.h")
    v = int(m.group(1))
    return f"{v // 1000}.{v % 1000 // 10}"


def render_table(header_text: str) -> str:
    """The C source of ``formats_table.h`` for the given header."""
    lines = [PREAMBLE.format(version=lcms_version(header_text))]
    lines += [f'    {{"{name}", TYPE_{name}}},\n' for name in format_names(header_text)]
    lines.append(POSTAMBLE)
    return "".join(lines)


def write_table(header: Path, target: Path = TABLE) -> int:
    """Regenerate ``formats_table.h``; returns the number of formats written."""
    text = header.read_text(encoding="utf-8")
    target.write_text(render_table(text), encoding="utf-8", newline="\n")
    return len(format_names(text))
